import{_ as d,k as c,C as t,a6 as i,l as a,z as r,A as o,j as p}from"./chunks/framework.BZrHWrhq.js";const g="/bwe/assets/images/general/getting-started/menu-page.png",h="/bwe/assets/images/general/getting-started/world-settings.png",b="/bwe/assets/images/general/getting-started/view-database.png",m="/bwe/assets/images/general/getting-started/integrations.png",S=JSON.parse('{"title":"Getting Started","description":"What to do after you install the application.","frontmatter":{"title":"Getting Started","page_title":"Getting Started","description":"What to do after you install the application.","nav_order":4,"mentions":["Aevarkan","8Crafter"]},"headers":[{"level":2,"title":"World View","slug":"world-view","link":"#world-view","children":[]},{"level":2,"title":"Database Tab","slug":"database-tab","link":"#database-tab","children":[]},{"level":2,"title":"Integrations Tab","slug":"integrations-tab","link":"#integrations-tab","children":[]},{"level":2,"title":"Scripting","slug":"scripting","link":"#scripting","children":[]}],"relativePath":"general/getting-started.md","filePath":"general/getting-started.md"}'),u={name:"general/getting-started.md"};function f(_,e,w,k,y,v){const s=o("template-WorkInProgress"),n=o("template-Update"),l=o("template-ExpandSection");return p(),c("div",null,[t(s),e[0]||(e[0]=i('<p>Upon opening the app, you will be greeted by a list of your Minecraft worlds. If your world doesn&#39;t appear, try pressing &quot;Show more&quot; at the bottom of the list.</p><p>To begin editing, open the world you&#39;ll be making changes to by clicking on its tab in the list.</p><p>You can refresh the worlds list by clicking the app logo on the left.</p><p><img src="'+g+'" alt="World directory"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If your world still doesn&#39;t show up after pressing &quot;Show more&quot;, then that is a bug. File an issue <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/issues" target="_blank" rel="noreferrer">here</a> with details of your Minecraft configuration.</p></div><h2 id="world-view" tabindex="-1">World View <a class="header-anchor" href="#world-view" aria-label="Permalink to &quot;World View&quot;">​</a></h2><p>Once you have opened a world, you will see a selection of tabs to the left, each pertaining to an aspect of the world you can edit. Here, the <code class="shiki"><span>World Settings</span></code> tab is selected.</p><p>Depending on the tab, you may have a selection of <code class="shiki"><span>Node</span></code>, <code class="shiki"><span>Prismarine-NBT</span></code>, <code class="shiki"><span>SNBT</span></code>, or another format of displaying the data. For most tabs, the <code class="shiki"><span>Node</span></code> editor format will be available.</p><p><img src="'+h+'" alt="World settings tab"></p><h2 id="database-tab" tabindex="-1">Database Tab <a class="header-anchor" href="#database-tab" aria-label="Permalink to &quot;Database Tab&quot;">​</a></h2><p>Minecraft Bedrock uses <a href="https://minecraft.wiki/w/Bedrock_Edition_level_format" target="_blank" rel="noreferrer">LevelDB</a> to store world data, a flat key-value database. Due to this flat nature, every single key-value pair can be sorted in one list. This is what the <code class="shiki"><span>View Files</span></code> tab displays.</p><p><img src="'+b+'" alt="Database view"></p><p>Unlike other editors, such as the Universal Minecraft Tool, Bedrock World Editor is capable of editing almost every single type of data in the LevelDB in a human-readable format, while other editors will either not allow you to edit many types, or only allow you to edit them as binary data.</p><h2 id="integrations-tab" tabindex="-1">Integrations Tab <a class="header-anchor" href="#integrations-tab" aria-label="Permalink to &quot;Integrations Tab&quot;">​</a></h2>',14)),t(n,{section:"section",details:"This section is missing information on the Lily's Money integration."}),e[1]||(e[1]=i('<p>As the Script API for Minecraft Bedrock is rather limiting, add-ons can struggle to implement advanced features. The <code class="shiki"><span>Integrations</span></code> tab allows add-ons to leverage Bedrock World Editor&#39;s capabilities, bypassing constraints of the Script API.</p><p>Currently, <a href="https://mcpedl.com/worldedit-be-addon/" target="_blank" rel="noreferrer">WorldEdit Bedrock</a> by <a href="https://github.com/SIsilicon" target="_blank" rel="noreferrer">SIsilicon</a> leverages Bedrock World Editor for its biome modification and structure import export features. For more information, see the dedicated integration page <a href="./../integrations/worldedit-bedrock">here</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Integrations are implemented on a case-by-case basis. If you would like to add an integration for your add-on, make a suggestion <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/issues/new?template=integration-suggestion.md" target="_blank" rel="noreferrer">here</a>.</p></div><p><img src="'+m+'" alt="Integrations tab"></p><h2 id="scripting" tabindex="-1">Scripting <a class="header-anchor" href="#scripting" aria-label="Permalink to &quot;Scripting&quot;">​</a></h2>',5)),t(l),e[2]||(e[2]=a("p",null,[r("Bedrock World Editor allows for scripting in JavaScript via the DevTools console which can be opened with "),a("code",{class:"shiki"},[a("span",null,"F12")]),r(". The scripting can modify your world data, allowing you to preform batch operations on your world.")],-1))])}const I=d(u,[["render",f]]);export{S as __pageData,I as default};
